public class Main{static long xsNext(long x){x^=x<<13;x^=x>>>7;x^=x<<17;return x;}public static void main(String[]a){int nv=50000, ne=nv*8; java.util.ArrayList<Integer>[] adj=new java.util.ArrayList[nv]; for(int i=0;i<nv;i++) adj[i]=new java.util.ArrayList<>(); long r=12345; for(int e=0;e<ne;e++){r=xsNext(r); int u=(int)Long.remainderUnsigned(r,nv); int v=(int)Long.remainderUnsigned(r>>>24,nv); adj[u].add(v);} long total=0; long seed=999; int[] dist=new int[nv]; java.util.ArrayDeque<Integer> q=new java.util.ArrayDeque<>(); for(int s=0;s<4;s++){seed=xsNext(seed); int src=(int)Long.remainderUnsigned(seed,nv); java.util.Arrays.fill(dist,-1); q.clear(); dist[src]=0; q.add(src); while(!q.isEmpty()){int u=q.poll(); int d=dist[u]; total+=d; for(int w:adj[u]) if(dist[w]<0){dist[w]=d+1; q.add(w);}}} System.out.println(nv+ne); System.out.println(Long.toUnsignedString(total));}}